def photo(name, title, at, off=None, x=0.6, y=0.47, h=600):
    d = dict(k='photo', name=name, title=title, xy=(x, y), at=at, h=h)
    if off is not None: d['off'] = off
    return d
def clock(at=0.0, id='clk', speed=-2.5, x=0.5, y=0.45, s=160):
    return dict(k='clock', xy=(x, y), at=at, id=id, speed=speed, s=s)

